export function shortestZeroPath(grid) {
  const rows=grid.length,cols=rows?grid[0].length:0;
  if(!rows||!cols||grid[0][0]!==0||grid[rows-1][cols-1]!==0)return -1;
  const q=[[0,0,1]],seen=new Set(['0,0']);let head=0;
  while(head<q.length){const [r,c,steps]=q[head++];if(r===rows-1&&c===cols-1)return steps;
    for(const [dr,dc] of [[1,0],[-1,0],[0,1],[0,-1]]){
      const nr=r+dr,nc=c+dc,k=nr+','+nc;
      if(nr<0||nc<0||nr>=rows||nc>=cols||grid[nr][nc]!==0||seen.has(k))continue;
      seen.add(k);q.push([nr,nc,steps+1]);
    }
  }
  return -1;
}
